import ModelProjectPanel from './ModelProjectPanel.jsx';
import Appearance from './Appearance.jsx';
import {applyTheme} from './theme.mjs';
import ToolpathPreview from './ToolpathPreview.jsx';
import {gcodeStats,parseToolpath} from './gcode.mjs';
import React,{useState,useEffect,useRef,useContext,createContext,useId} from 'react';
import {createRoot} from 'react-dom/client';
import {House,Calculator,Layers,ShoppingBag,FolderOpen,ChartNoAxesCombined,Settings,Plus,ArrowUpRight,ArrowDownLeft,Package,Flame,Zap,Check,ChevronRight,Search,X,Camera,Download,Upload,RefreshCw,ShieldCheck,TriangleAlert,Undo2,Trash2,Coins,Menu,Printer,Bell,BookOpen,Heart,Palette,Image as ImageIcon} from 'lucide-react';
import {VERSION,emptyState,uid,today,money,saveSpool,remaining,consumed,calculate,recordProduction,reverseProduction,recordSale,report} from './domain.mjs';
import {load,save,encryptBackup,decryptBackup} from './storage.mjs';
import {cities,githubBackup,checkUpdate,exportFile,photo,installUpdate,fetchTariffs} from './services.mjs';
import './style.css';
import './refresh.css';
import './theme.css';
import ModelViewer,{importModel} from './ModelViewer.jsx';
import {estimateGeometry,formatTime} from './model-tools.mjs';
import Tutorials,{BackupGuide} from './Tutorials.jsx';

const NAV=[['home','Visão geral',House],['calculator','Calculadora',Calculator],['projects','Projetos',FolderOpen],['spools','Filamentos',Layers],['production','Produção',Printer],['sales','Vendas',ShoppingBag],['reports','Relatórios',ChartNoAxesCombined],['tutorials','Tutoriais',BookOpen],['collaboration','Colaboração',Heart],['appearance','Personalizar cores',Palette],['updates','Atualizações',RefreshCw],['settings','Configurações',Settings]];
const COLORS=['#ffca08','#171717','#faf8ed','#f57c00','#ed407a','#e53935','#5e35b1','#1e88e5','#00acc1','#43a047','#8d6e63','#90a4ae'];
const ErrorContext=createContext('');
const UF=['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];
function Button({children,kind='',...props}){return <button className={'button '+kind} {...props}>{children}</button>}
function Field({label,children,hint}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Input({label,hint,...props}){return <Field label={label} hint={hint}><input {...props}/></Field>}
function Num({label,value,onChange,min=0,step='any',...props}){return <Input label={label} type="number" inputMode="decimal" min={min} step={step} value={value} onChange={e=>onChange(e.target.value)} {...props}/>}
function Empty({title='Nada por aqui ainda',text='Comece adicionando seu primeiro registro.',children}){return <div className="empty"><Package size={35}/><h3>{title}</h3><p>{text}</p>{children}</div>}
function Modal({title,children,onClose}){const error=useContext(ErrorContext);const ref=useRef();useEffect(()=>{const el=ref.current;el.showModal();return()=>{if(el.open)el.close();};},[]);return <dialog ref={ref} onCancel={onClose} onClick={e=>{if(e.target===ref.current)onClose();}}><div className="modal-head"><h2>{title}</h2><button className="icon" aria-label="Fechar" onClick={onClose}><X/></button></div><div className="modal-body">{error&&<div className="alert" role="alert">{error}</div>}{children}</div></dialog>}
function Spool({color,size=68}){const id=useId().replace(/:/g,'');return <svg className="spool-art" width={size} height={size} viewBox="0 0 112 100" aria-label="Carretel de filamento" role="img"><defs><linearGradient id={id+'f'} x1="0" y1="0" x2="0" y2="1"><stop stopColor="#fff" stopOpacity=".45"/><stop offset=".25" stopColor={color}/><stop offset=".65" stopColor={color}/><stop offset="1" stopColor="#000" stopOpacity=".6"/></linearGradient><linearGradient id={id+'b'} x1="0" y1="0" x2="1" y2="1"><stop stopColor="#5d6064"/><stop offset=".45" stopColor="#24272b"/><stop offset="1" stopColor="#101114"/></linearGradient><radialGradient id={id+'face'} cx=".3" cy=".2" r=".9"><stop stopColor="#44484c"/><stop offset=".5" stopColor="#222529"/><stop offset="1" stopColor="#0c0d10"/></radialGradient></defs><ellipse cx="57" cy="92" rx="43" ry="5" fill="#000" opacity=".5"/><ellipse cx="31" cy="48" rx="25" ry="41" fill={'url(#'+id+'b)'} stroke="#74777b" strokeWidth="1.2"/><path d="M31 12H70C84 12 94 28 94 49S84 86 70 86H31C18 82 15 68 15 49S18 17 31 12Z" fill={color}/><path d="M31 12H70C84 12 94 28 94 49S84 86 70 86H31C18 82 15 68 15 49S18 17 31 12Z" fill={'url(#'+id+'f)'} opacity=".75"/>{Array.from({length:17},(_,i)=><path key={i} d={`M${27+i*2.6} 14C${10+i*2.6} 24 ${10+i*2.6} 73 ${27+i*2.6} 85`} fill="none" stroke="#000" opacity=".14" strokeWidth=".7"/>)}<ellipse cx="73" cy="48" rx="28" ry="42" fill={'url(#'+id+'b)'} stroke="#777b7f" strokeWidth="1.2"/><ellipse cx="75" cy="48" rx="24" ry="37" fill={'url(#'+id+'face)'} stroke="#111216" strokeWidth="1.2"/>{[0,60,120,180,240,300].map(a=><path key={a} d="M73 15C79 15 82 19 82 25L78 32 73 30Z" transform={`rotate(${a} 74 48)`} fill="#0c0d10" stroke="#494c50" strokeWidth=".65"/>)}<ellipse cx="74" cy="48" rx="11" ry="17" fill="#0a0b0d" stroke="#74787b" strokeWidth="1.1"/><ellipse cx="75" cy="48" rx="6.5" ry="11.5" fill="#202329" stroke="#050608" strokeWidth="2"/><path d="M61 17C50 32 50 63 61 79" stroke="#d5d8db" strokeOpacity=".23" strokeWidth="1" fill="none"/></svg>}

function Thumb({project}){return project?.image?<img className="thumb" src={project.image} alt={project.name}/>:<div className="thumb placeholder"><ImageIcon size={24}/></div>}
function Stat({label,value,icon:Icon,accent=false,detail}){return <div className={'stat '+(accent?'accent':'')}><div className="stat-label"><Icon size={19}/>{label}</div><strong>{value}</strong>{detail&&<small>{detail}</small>}</div>}
function App(){const [state,setState]=useState(null),[page,setPage]=useState('home'),[modal,setModal]=useState(null),[notice,setNotice]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),[menu,setMenu]=useState(false);useEffect(()=>{applyTheme(state?.settings.theme);},[state?.settings.theme]);const current=useRef(null),lock=useRef(false);useEffect(()=>{(import.meta.env.DEV&&new URLSearchParams(location.search).has('visual-test')?import('../tests/fixture-state.mjs').then(m=>m.fixtureState()):load()).then(s=>{setState(s);current.current=s;navigator.storage?.persist?.().catch(()=>{});}).catch(e=>setError(e.message));},[]);useEffect(()=>{if(notice){const t=setTimeout(()=>setNotice(''),6000);return()=>clearTimeout(t);}},[notice]);async function mutate(fn,message='Salvo no aparelho'){if(lock.current)throw Error('Aguarde o salvamento atual.');lock.current=true;setBusy(true);try{const next=await save(fn(current.current),current.current.revision);current.current=next;setState(next);setNotice(message);return next;}finally{lock.current=false;setBusy(false);}}async function run(fn){setError('');try{await fn();}catch(e){setError(e.message||'Não foi possível concluir.');}}const close=()=>setModal(null);const go=p=>{setPage(p);setMenu(false);};if(!state)return <div className="loading"><img src="./logo.png" width="64"/><h1>JAGUAR LAB</h1><p>{error||'Abrindo seu ateliê…'}</p></div>;
const r=report(state,today().slice(0,7)+'-01');const low=state.spools.filter(s=>remaining(state,s.id)<=Number(state.settings.lowStock||200));
return <ErrorContext.Provider value={error}><div className="shell"><aside className={menu?'open':''}><div className="brand"><img src="./logo.png"/><div>JAGUAR <b>LAB</b><small>SEU ATELIÊ, NO CONTROLE.</small></div></div><div className="workspace"><span className="avatar"><img src="./logo.png" alt="JAGUAR LAB"/></span><div>{state.settings.shop}<small><span className="dot"/> Dados neste aparelho</small></div></div><p className="nav-label">ESPAÇO DE TRABALHO</p><nav>{NAV.map(([id,title,Icon])=><button key={id} onClick={()=>go(id)} className={page===id?'selected':''}><Icon size={20}/>{title}{id==='spools'&&low.length>0&&<em>{low.length}</em>}</button>)}</nav><div className="sidebar-foot"><ShieldCheck size={19}/><span>Seu trabalho fica com você.<small>Offline • versão {VERSION}</small></span></div></aside>{menu&&<div className="scrim" onClick={()=>setMenu(false)}/>}
<main><header><div className="app-heading"><button className="icon mobile-menu" aria-label="Abrir menu" onClick={()=>setMenu(!menu)}><Menu size={23}/></button><h1>{NAV.find(n=>n[0]===page)[1]}</h1></div><div className="header-right"><button className="header-action appearance-action" onClick={()=>go('appearance')}><Palette size={17}/><span>Cores</span></button><button className="header-action" onClick={()=>go('updates')}><RefreshCw size={17}/><span>Atualizar</span></button><button className="header-action collaboration-action" onClick={()=>go('collaboration')}><Heart size={17}/><span>Colaboração</span></button><span className="local-badge"><span className="dot"/> Salvo neste aparelho</span><button className="icon help-button" aria-label="Abrir tutoriais" onClick={()=>go('tutorials')}><BookOpen size={20}/></button><button className="icon" aria-label="Ver alertas de estoque" onClick={()=>go('spools')}><Bell size={20}/></button><button className="avatar" aria-label="Perfil do ateliê" onClick={()=>go('settings')}><img src="./logo.png" alt="Logo JAGUAR LAB"/></button></div></header>
<div className="content">{import.meta.env.DEV&&new URLSearchParams(location.search).has('visual-test')&&<div className="demo-banner">Demonstração visual · dados fictícios</div>}<div className="page-title"><div><p className="eyebrow">{page==='home'?'DA IDEIA À ÚLTIMA CAMADA':'JAGUAR LAB / SEU NEGÓCIO'} </p><h1>{page==='home'?'Seu próximo nível começa aqui.':NAV.find(n=>n[0]===page)[1]}</h1><p>{({home:'Produção, materiais e resultados. Tudo no mesmo lugar.',calculator:'Transforme gramas e horas em um preço que faz sentido.',projects:'Suas ideias, referências e peças em um só lugar.',spools:'Cada cor tem uma história. Cada grama também.',production:'Registre o que saiu da mesa — e o material que foi junto.',sales:'Acompanhe suas entregas, pagamentos e resultados.',reports:'Entenda o que vende mais e onde seu material vai.',settings:'Seu ateliê, suas preferências e seus backups.'})[page]}</p></div>{page==='home'&&<Button onClick={()=>setModal('project')}><Plus size={18}/> Novo projeto</Button>}</div>
{error&&<div role="alert" className="alert error"><TriangleAlert size={18}/>{error}<button className="icon" onClick={()=>setError('')} aria-label="Dispensar erro"><X size={16}/></button></div>}
{page==='appearance'&&<Appearance state={state} mutate={mutate} run={run} busy={busy}/>}
{page==='updates'&&<UpdatePanel state={state} run={run} notice={setNotice} autoCheck/>}
{page==='home'&&<Dashboard state={state} r={r} low={low} go={go} newProject={()=>setModal('project')}/>}
{page==='spools'&&<Spools state={state} edit={s=>setModal({type:'spool',item:s})} details={s=>setModal({type:'spool-detail',item:s})}/>}
{page==='projects'&&<Projects state={state} edit={p=>setModal({type:'project',item:p})}/>}
{page==='calculator'&&<CalculatorPage state={state} mutate={mutate} run={run} busy={busy} go={go}/>}
{page==='production'&&<section className="panel"><div className="section-title"><h2>Histórico de impressões</h2><Button onClick={()=>go('calculator')}><Plus size={17}/> Registrar impressão</Button></div><p className="muted">O peso informado deve incluir suportes e desperdício. Impressões com falha também consomem material.</p>{!state.productions.length?<Empty/>:<div className="table-wrap"><table><thead><tr><th>Projeto / data</th><th>Quantidade</th><th>Material</th><th>Custo total</th><th>Situação</th><th/></tr></thead><tbody>{[...state.productions].reverse().map(p=><tr key={p.id}><td><b>{p.projectName}</b><small>{p.date.split('-').reverse().join('/')} {p.note&&`· ${p.note}`}</small></td><td>{p.quantity}</td><td>{p.materials.reduce((n,m)=>n+m.grams,0).toFixed(1)} g</td><td>{money(p.total)}</td><td><span className={'badge '+(p.reversedAt?'':p.status==='failed'?'warn':'green')}>{p.reversedAt?'Estornada':p.status==='failed'?'Falha':'Concluída'}</span></td><td>{!p.reversedAt&&<Button kind="subtle" onClick={()=>setModal({type:'confirm',title:'Estornar impressão?',text:'O consumo será devolvido aos carretéis. O registro continuará no histórico. Vendas vinculadas precisam ser canceladas antes.',action:()=>mutate(s=>reverseProduction(s,p.id),'Impressão estornada')})}><Undo2 size={15}/> Estornar</Button>}</td></tr>)}</tbody></table></div>}</section>}
{page==='sales'&&<Sales state={state} go={go} add={()=>setModal('sale')} mutate={mutate} run={run} confirm={setModal}/>}
{page==='reports'&&<Reports state={state} addExpense={()=>setModal('expense')} mutate={mutate} run={run}/>}
{page==='tutorials'&&<Tutorials/>}
{page==='collaboration'&&<Collaboration/>}
{page==='settings'&&<SettingsPage state={state} mutate={mutate} run={run} notice={setNotice} confirm={setModal}/>}
</div><footer>JAGUAR LAB <span>Feito para quem transforma ideias em peças.</span><b>v{VERSION}</b></footer></main>
<div className="bottom-nav">{[['home','Início',House],['calculator','Calcular',Calculator],['spools','Estoque',Layers],['sales','Vendas',ShoppingBag]].map(([id,title,Icon])=><button key={id} className={id===page?'active':''} onClick={()=>go(id)}><Icon size={21}/><span>{title}</span></button>)}</div>
{notice&&<div className="toast" role="status"><Check size={18}/>{notice}</div>}
{modal&&(modal==='project'||modal.type==='project')&&<ProjectForm item={modal.item} close={close} state={state} mutate={mutate} run={run} busy={busy}/>}
{modal?.type==='spool-detail'&&<SpoolDetails item={modal.item} state={state} close={close} edit={s=>setModal({type:'spool',item:s})}/>}
{modal?.type==='spool'&&<SpoolForm item={modal.item} close={close} mutate={mutate} run={run} busy={busy}/>}
{modal==='sale'&&<SaleForm state={state} close={close} mutate={mutate} run={run} busy={busy}/>}
{modal==='expense'&&<ExpenseForm close={close} mutate={mutate} run={run} busy={busy}/>}
{modal?.type==='confirm'&&<Modal title={modal.title} onClose={close}><p>{modal.text}</p><div className="actions"><Button kind="subtle" onClick={close}>Voltar</Button><Button disabled={busy} onClick={()=>run(async()=>{await modal.action();close();})}>Confirmar</Button></div></Modal>}
</div></ErrorContext.Provider>}

function Spools({state,edit,details}){const [search,setSearch]=useState(''),[material,setMaterial]=useState('Todos');const list=state.spools.filter(s=>(material==='Todos'||s.material===material)&&`${s.name} ${s.brand} ${s.line}`.toLowerCase().includes(search.toLowerCase()));const types=['Todos',...new Set(['PLA','PETG','ABS',...state.spools.map(s=>s.material)])];return <><section className="inventory-summary"><Layers size={28}/><div><span>Estoque total</span><strong>{(state.spools.reduce((n,s)=>n+remaining(state,s.id),0)/1000).toLocaleString('pt-BR',{maximumFractionDigits:2})} <small>kg</small></strong></div><span>{state.spools.length} carretéis</span></section><div className="filter-tabs">{types.map(x=><button key={x} className={x===material?'active':''} onClick={()=>setMaterial(x)}>{x===material&&<Check size={15}/>} {x}</button>)}</div><div className="search inventory-search"><Search size={17}/><input placeholder="Buscar cor, marca ou modelo" aria-label="Buscar filamentos" value={search} onChange={e=>setSearch(e.target.value)}/></div>{!list.length?<section className="panel"><Empty title="Nenhum filamento encontrado" text="Cadastre seus carretéis ou escolha outro filtro."/></section>:<div className="filament-list">{list.map(s=>{const rest=remaining(state,s.id),low=rest<=Number(state.settings.lowStock||200);return <button className="filament-card" key={s.id} onClick={()=>details(s)}><Spool color={s.color} size={76}/><span className="grow filament-label"><strong>{s.name}</strong><small>{s.brand}{s.line&&` · ${s.line}`}</small><span className="badge material-tag">{s.material}</span>{low&&<span className="badge warn"><TriangleAlert size={11}/> Estoque baixo</span>}</span><span className="filament-amount">{rest.toLocaleString('pt-BR',{maximumFractionDigits:1})} <small>g</small></span><ChevronRight size={18}/></button>})}</div>}<div className="primary-footer"><Button onClick={()=>edit(null)}><Plus size={19}/> Adicionar filamento</Button></div></>}

function SpoolForm({item,close,mutate,run,busy}){const [v,setV]=useState(item||{name:'',brand:'',line:'',material:'PLA',color:'#ffca08',initialGrams:1000,price:'',purchaseDate:today()});const change=(key,val)=>setV({...v,[key]:val});return <Modal title={item?'Editar carretel':'Novo carretel'} onClose={close}><form onSubmit={e=>{e.preventDefault();run(async()=>{await mutate(s=>saveSpool(s,v));close();});}}><div className="spool-preview"><Spool color={v.color} size={110}/><div><p>Escolha a cor do seu filamento</p><div className="swatches">{COLORS.map(c=><button key={c} type="button" title={c} aria-label={`Cor ${c}`} className={v.color===c?'chosen':''} style={{background:c}} onClick={()=>change('color',c)}/>)}</div><input type="color" aria-label="Cor personalizada" value={v.color} onChange={e=>change('color',e.target.value)}/></div></div><div className="form-grid"><Input label="Nome da cor" required value={v.name} onChange={e=>change('name',e.target.value)} placeholder="Ex.: Amarelo solar"/><Input label="Marca" required value={v.brand} onChange={e=>change('brand',e.target.value)} placeholder="Ex.: Voolt, Vult, Bambu…"/><Input label="Linha / modelo" value={v.line} onChange={e=>change('line',e.target.value)} placeholder="Ex.: Silk, Matte, Basic"/><Field label="Material"><select value={v.material} onChange={e=>change('material',e.target.value)}>{['PLA','PLA+','PETG','ABS','ASA','TPU','Nylon','Outro'].map(x=><option key={x}>{x}</option>)}</select></Field><Num label="Peso de filamento inicial (g)" value={v.initialGrams} onChange={x=>change('initialGrams',x)} min={0.01} required/><Num label="Preço pago pelo rolo (R$)" value={v.price} onChange={x=>change('price',x)} required/><Input label="Data da compra" type="date" required value={v.purchaseDate} onChange={e=>change('purchaseDate',e.target.value)}/></div><p className="note">Cadastre cada rolo separadamente. Para um rolo já aberto, informe o peso restante e o valor proporcional desse material.</p><div className="actions"><Button kind="subtle" type="button" onClick={close}>Cancelar</Button><Button disabled={busy}>Salvar carretel</Button></div></form></Modal>}
function Projects({state,edit}){const [search,setSearch]=useState('');return <><div className="toolbar"><div className="search"><Search size={18}/><input aria-label="Buscar projeto" placeholder="Buscar seu próximo projeto…" value={search} onChange={e=>setSearch(e.target.value)}/></div><Button onClick={()=>edit(null)}><Plus size={18}/> Novo projeto</Button></div>{!state.projects.length?<section className="panel"><Empty title="Da sua imaginação para a mesa" text="Adicione uma foto e organize suas peças antes de imprimir."/></section>:<div className="project-grid">{state.projects.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())).map(p=><section className="panel project-card" key={p.id}>{p.image?<img className="project-image" src={p.image} alt={p.name}/>:<div className="project-image no-image"><Package size={50}/><span>Adicione uma referência</span></div>}<div className="project-info"><h2>{p.name}</h2><p>{p.description||'Sem descrição'}</p><div className="split"><span className="badge">{state.productions.filter(x=>x.projectId===p.id&&!x.reversedAt&&x.status==='done').reduce((n,x)=>n+x.quantity,0)} peças impressas</span><Button kind="subtle" onClick={()=>edit(p)}>Editar <ChevronRight size={14}/></Button></div></div></section>)}</div>}</>}
function ProjectForm({item,close,mutate,run,busy}){const [v,setV]=useState(item||{id:uid(),name:'',description:'',image:'',createdAt:new Date().toISOString()}),[processing,setProcessing]=useState(false);const viewer=useRef(null);return <Modal title={item?'Editar projeto':'Novo projeto'} onClose={close}><form onSubmit={e=>{e.preventDefault();run(async()=>{if(!v.name.trim())throw Error('Informe o nome do projeto.');const image=v.image||(viewer.current?.snapshot())||v.model?.thumbnail||'';await mutate(s=>({...s,projects:[...s.projects.filter(p=>p.id!==v.id),{...v,image,name:v.name.trim()}]}));close();});}}><Input label="Nome do projeto" required maxLength={150} value={v.name} onChange={e=>setV({...v,name:e.target.value})} placeholder="Ex.: Vaso orgânico"/><div className="upload-options"><label className="button subtle"><Camera size={18}/> Adicionar foto<input type="file" hidden accept="image/jpeg,image/png,image/webp" onChange={e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;setProcessing(true);run(async()=>{try{const image=await photo(file);setV(x=>({...x,image}));}finally{setProcessing(false);}});}}/></label><label className="button"><Package size={18}/> Importar STL / 3MF<input type="file" hidden accept=".stl,.3mf" onChange={e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;setProcessing(true);run(async()=>{try{await new Promise(resolve=>setTimeout(resolve,30));const model=await importModel(file);setV(x=>({...x,model,name:x.name||file.name.replace(/\.(stl|3mf)$/i,'')}));}finally{setProcessing(false);}});}}/></label></div>{processing&&<p className="note">Preparando arquivo… aguarde nesta tela.</p>}{v.model&&<><ModelViewer model={v.model} onReady={api=>{viewer.current=api;}}/><div className="split"><p className="note">{v.model.name} · {(v.model.size/1024/1024).toFixed(1)} MB</p><button className="text-button" type="button" onClick={()=>setV({...v,model:null})}>Remover modelo</button></div>{v.model.plates?.length>0&&<p className="note">Dados do fatiador encontrados em {v.model.plates.length} mesa(s). Use a calculadora para conferir.</p>}</>}{v.image&&<div className="photo-preview"><img src={v.image} alt="Foto do projeto"/><button type="button" className="text-button" onClick={()=>setV({...v,image:''})}>Remover foto</button></div>}{!v.image&&!v.model&&<p className="note">Adicione uma foto ou um arquivo 3D. A prévia será usada como imagem do projeto. Modelos: até 20 MB e 250 mil triângulos.</p>}<Field label="Descrição / observações"><textarea value={v.description} rows={2} maxLength={2000} onChange={e=>setV({...v,description:e.target.value})}/></Field><div className="actions"><Button type="button" kind="subtle" onClick={close}>Cancelar</Button><Button disabled={busy||processing}>{processing?'Preparando…':'Salvar projeto'}</Button></div></form></Modal>}


function CalculatorPage({state,mutate,run,busy,go}){const [v,setV]=useState(()=>({projectId:sessionStorage.getItem('onca-project')||'',materials:[{spoolId:state.spools[0]?.id||'',grams:''}],hours:'',watts:state.settings.watts,tariff:state.settings.tariff,machine:0,labor:0,extras:0,margin:30,fee:0,quantity:1,date:today(),status:'done',note:''}));const [saved,setSaved]=useState(false),[sliced,setSliced]=useState(null),[slicedError,setSlicedError]=useState('');const [manual,setManual]=useState(!state.spools.length),[pricePerKg,setPricePerKg]=useState('90');const set=(k,val)=>{setSaved(false);setV(x=>({...x,[k]:val}));};const material=(i,key,val)=>set('materials',v.materials.map((m,n)=>n===i?{...m,[key]:val}:m));const project=state.projects.find(p=>p.id===v.projectId);let q=null;try{q=calculate(state,{...v,materials:manual?[]:v.materials,manualMaterial:manual?{grams:v.materials[0].grams,pricePerKg}:undefined});}catch{}const useModel=estimate=>{setV(x=>({...x,note:estimate.rough?'Estimativa geométrica: conferir tempo e material no fatiador.':x.note,hours:estimate.seconds?Number((estimate.seconds/3600).toFixed(3)):x.hours,materials:estimate.grams?[{spoolId:x.materials[0]?.spoolId||state.spools[0]?.id||'',grams:Number(estimate.grams.toFixed(2))}]:x.materials}));setSaved(false);};return <div className="calc-layout reference-calculator"><div className="stack"><section className="panel calculator-inputs"><Field label="Projeto (opcional)"><select value={v.projectId} onChange={e=>set('projectId',e.target.value)}><option value="">Cálculo rápido — sem projeto</option>{state.projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field>{!state.projects.length&&<button className="text-button" onClick={()=>go('projects')}>Adicionar projeto <Plus size={15}/></button>}<p className="note">Você pode calcular só com o peso e o tempo mostrados no fatiador. Não é necessário importar um objeto.</p><Field label="Origem do preço"><select value={manual?'manual':'stock'} onChange={e=>setManual(e.target.value==='manual')}><option value="stock">Carretel do meu estoque</option><option value="manual">Informar preço por kg</option></select></Field>{manual?<Num label="Preço do filamento (R$/kg)" value={pricePerKg} onChange={setPricePerKg}/>:<Field label="Filamento"><FilamentPicker state={state} value={v.materials[0].spoolId} onChange={x=>material(0,'spoolId',x)}/></Field>}<label className="button subtle"><Upload size={18}/> Importar dados do fatiador<input hidden type="file" accept=".gcode,.gco,.gc" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{setSlicedError('');if(file.size>20*1024*1024)throw Error('Exporte um G-code de até 20 MB.');const text=await file.text(),stats=gcodeStats(text);if(!stats.seconds&&!stats.grams)throw Error('Este G-code não informa tempo ou peso. Digite os valores exibidos no fatiador.');setSliced({...stats,name:file.name,path:parseToolpath(text)});}catch(err){setSlicedError(err.message);}e.target.value='';}}/></label><p className="note">No Anycubic, Orca, Bambu ou Prusa: fatie a mesa e exporte o G-code. A leitura é local. Tempo e peso continuam sendo estimativas do fatiador.</p>{slicedError&&<p role="alert" className="note warning">{slicedError}</p>}{sliced&&<section className="slicer-result"><strong>{sliced.name}</strong><p className="note">{sliced.source}</p><ToolpathPreview path={sliced.path}/><div className="model-estimates"><div><small>Tempo do fatiador</small><strong>{sliced.seconds?formatTime(sliced.seconds):'Não informado'}</strong></div><div><small>Material do fatiador</small><strong>{sliced.grams?sliced.grams.toFixed(2)+' g':'Não informado'}</strong></div></div>{sliced.filaments.length>1&&<p className="note warning">Vários filamentos: distribua o peso de cada cor antes de registrar a impressão.</p>}<Button kind="subtle" onClick={()=>useModel(sliced)}>Usar tempo e peso na calculadora</Button></section>}<div className="quick-inputs"><Num label="Peso (g)" value={v.materials[0].grams} onChange={x=>material(0,'grams',x)}/><Num label="Tempo (horas)" value={v.hours} onChange={x=>set('hours',x)}/><Num label="Energia (R$/kWh)" value={v.tariff} onChange={x=>set('tariff',x)}/></div>{!manual&&v.materials.slice(1).map((m,n)=><div className="material-row extra-material" key={n+1}><Field label="Outro filamento"><FilamentPicker state={state} value={m.spoolId} onChange={x=>material(n+1,'spoolId',x)}/></Field><Num label="Peso (g)" value={m.grams} onChange={x=>material(n+1,'grams',x)}/><button className="icon" aria-label="Remover material" onClick={()=>set('materials',v.materials.filter((_,i)=>i!==n+1))}><X size={16}/></button></div>)}<button className="text-button" disabled={manual} onClick={()=>set('materials',[...v.materials,{spoolId:state.spools[0]?.id||'',grams:''}])}><Plus size={15}/> Usar outra cor / carretel</button><section className="profit-controls"><h2>Quanto você quer ganhar?</h2><Field label="Como aplicar o percentual"><select value={v.profitMode||'margin'} onChange={e=>set('profitMode',e.target.value)}><option value="margin">Margem sobre o preço de venda</option><option value="markup">Acréscimo sobre o custo</option></select></Field><Num label={(v.profitMode==='markup'?'Acréscimo':'Margem de lucro')+' (%)'} value={v.margin} onChange={x=>set('margin',x)}/><div className="filter-tabs">{(v.profitMode==='markup'?[30,50,100,150,200]:[20,30,40,50,60]).map(n=><button key={n} className={Number(v.margin)===n?'active':''} onClick={()=>set('margin',n)}>{n}%</button>)}</div><p className="note">{v.profitMode==='markup'?'100% de acréscimo dobra o custo antes das taxas.':'50% de margem significa que metade do preço de venda fica como lucro, após os custos e as taxas informadas.'} Inclua máquina, trabalho e embalagem nos custos abaixo.</p>{!q&&Number(v.materials[0].grams)>0&&<p role="alert" className="note warning">Confira o carretel, os valores e os percentuais. A margem somada às taxas precisa ficar abaixo de 100%; acréscimo pode passar de 100%.</p>}</section><details className="advanced-costs"><summary>Custos e ajustes da impressão <ChevronRight size={16}/></summary><div className="form-grid"><Num label="Consumo médio (W)" value={v.watts} onChange={x=>set('watts',x)}/><Num label="Máquina (R$/hora)" value={v.machine} onChange={x=>set('machine',x)}/><Num label="Mão de obra (R$)" value={v.labor} onChange={x=>set('labor',x)}/><Num label="Embalagem / extras (R$)" value={v.extras} onChange={x=>set('extras',x)}/><Num label="Taxas da venda (%)" value={v.fee} onChange={x=>set('fee',x)}/><Num label="Peças no lote" min={1} step={1} value={v.quantity} onChange={x=>set('quantity',x)}/><Input label="Data da produção" type="date" value={v.date} onChange={e=>set('date',e.target.value)}/><Field label="Resultado"><select value={v.status} onChange={e=>set('status',e.target.value)}><option value="done">Concluída</option><option value="failed">Falhou · consumiu material</option></select></Field></div><Input label="Observações" value={v.note} onChange={e=>set('note',e.target.value)}/><p className="note">Inclua suportes, purga e perdas no peso total do lote. Margem e taxas são percentuais sobre o preço de venda.</p></details>{!Number(v.tariff)&&<p className="note warning">Defina a tarifa de energia para incluir a luz no custo.</p>}</section>{project?.model&&<ModelProjectPanel key={project.id} project={project} apply={useModel} busy={busy} saveProfile={profile=>run(async()=>{await mutate(s=>({...s,projects:s.projects.map(p=>p.id===project.id?{...p,estimateProfile:profile}:p)}),'Perfil de estimativa salvo nesta peça.');})}/>}</div><div className="calc-result"><section className="panel cost-card"><h2><Layers size={19}/> Detalhamento de custos</h2><div className="cost-lines">{[['Filamento',q?.materialCost],['Energia',q?.energy],['Máquina e mão de obra',(q?.machine||0)+(q?.labor||0)],['Outros custos',q?.extras]].map(([title,val])=><div key={title}><span>{title}</span><b>{money(val)}</b></div>)}<div className="total"><b>Custo total</b><b>{money(q?.total)}</b></div></div></section><div className="price-box"><span>Preço de venda</span><strong>{money(q?.price)}</strong></div><div className="profit-box"><ChartNoAxesCombined size={20}/><span>Lucro estimado</span><strong>{money(q?.profit)}</strong></div>{q&&Number(v.quantity)>1&&<p className="note">{money(q.price/Number(v.quantity))} por peça · lote de {v.quantity}</p>}<div className="stack calc-actions"><Button kind="subtle" disabled={busy||!q} onClick={()=>run(async()=>{await mutate(s=>({...s,projects:v.projectId?s.projects.map(p=>p.id===v.projectId?{...p,quote:{...v,manualMaterial:manual?{grams:v.materials[0].grams,pricePerKg}:undefined,tariffDate:state.settings.tariffDate},quoteAt:new Date().toISOString()}:p):[...s.projects,{id:uid(),name:'Orçamento rápido '+new Date().toLocaleDateString('pt-BR'),description:'Cálculo sem arquivo 3D',quote:{...v,manualMaterial:manual?{grams:v.materials[0].grams,pricePerKg}:undefined},quoteAt:new Date().toISOString()}]}),'Orçamento salvo. Estoque preservado.');})}><Download size={18}/> Salvar orçamento</Button><Button disabled={busy||saved||!q||manual||!v.projectId} onClick={()=>run(async()=>{await mutate(s=>recordProduction(s,{...v,id:uid()}),'Impressão registrada. Estoque atualizado.');setSaved(true);})}><Check size={18}/>{saved?'Impressão registrada':v.status==='failed'?'Registrar falha e consumo':'Registrar impressão'}</Button></div><p className="note">O cálculo e o orçamento funcionam sem objeto. Para registrar consumo, selecione um projeto (pode ser sem arquivo) e um carretel cadastrado.</p>{project?.quote&&<button className="text-button" onClick={()=>{setV({...v,...project.quote,date:today()});setManual(!!project.quote.manualMaterial);if(project.quote.manualMaterial)setPricePerKg(project.quote.manualMaterial.pricePerKg);setSaved(false);}}>Carregar orçamento salvo <ChevronRight size={15}/></button>}</div></div>}


function Sales({state,add,mutate,run,confirm,go}){const [filter,setFilter]=useState('Todas');const r=report(state,today().slice(0,7)+'-01');const list=[...state.sales].reverse().filter(s=>filter==='Todas'||!s.cancelledAt&&(filter==='Pagas'?s.paid:!s.paid));return <><div className="stats sales-stats"><Stat label="Vendas neste mês" value={money(r.revenue)} icon={ShoppingBag} accent/><Stat label="Pedidos no mês" value={String(r.sales.length)} icon={ShoppingBag}/><Stat label="Ticket médio" value={money(r.sales.length?r.revenue/r.sales.length:0)} icon={Layers}/></div><div className="balance-strip"><span>Recebido <b>{money(r.received)}</b></span><span>A receber <b>{money(r.revenue-r.received)}</b></span></div><section className="panel sales-panel"><div className="section-title"><h2><ShoppingBag size={18}/> Pedidos recentes</h2><span className="badge">{state.sales.length} registros</span></div><div className="filter-tabs">{['Todas','Pagas','A receber'].map(x=><button key={x} className={x===filter?'active':''} onClick={()=>setFilter(x)}>{x}</button>)}</div>{!list.length?<div className="compact-empty"><ShoppingBag size={30}/><p>Nenhuma venda neste filtro.</p></div>:list.map(s=><details className="sale-card" key={s.id}><summary><Thumb project={state.projects.find(p=>p.id===s.projectId)}/><span className="grow"><strong>{s.projectName}</strong><small>{money(s.amount)}</small></span><span className={'badge '+(s.cancelledAt?'':s.paid?'green':'warn')}>{s.cancelledAt?'Cancelada':s.paid?'Pago':'A receber'}</span><ChevronRight size={17}/></summary><div className="sale-details"><div className="detail-grid"><div><span>Cliente</span><strong>{s.customer||'Não informado'}</strong></div><div><span>Data</span><strong>{s.date.split('-').reverse().join('/')}</strong></div><div><span>Quantidade</span><strong>{s.quantity} peças</strong></div><div><span>Lucro desta venda</span><strong>{money(s.amount-s.cost-s.fee)}</strong></div></div>{!s.cancelledAt&&<div className="actions"><Button kind="subtle" onClick={()=>confirm({type:'confirm',title:'Cancelar venda?',text:'A peça permanece produzida. O filamento não será devolvido ao estoque.',action:()=>mutate(d=>({...d,sales:d.sales.map(x=>x.id===s.id?{...x,cancelledAt:new Date().toISOString()}:x)}),'Venda cancelada')})}>Cancelar venda</Button><Button onClick={()=>run(()=>mutate(d=>({...d,sales:d.sales.map(x=>x.id===s.id?{...x,paid:!x.paid}:x)})))}>{s.paid?'Marcar a receber':'Marcar como pago'}</Button></div>}</div></details>)}</section><MonthlyGoal state={state} revenue={r.revenue} go={go}/><div className="primary-footer"><Button onClick={add}><Plus size={18}/> Nova venda</Button></div></>}

function SaleForm({state,close,mutate,run,busy}){const available=state.productions.filter(p=>!p.reversedAt&&p.status==='done'&&p.quantity>state.sales.filter(s=>s.productionId===p.id&&!s.cancelledAt).reduce((n,s)=>n+s.quantity,0));const [v,setV]=useState({productionId:available[0]?.id||'',quantity:1,amount:'',fee:0,customer:'',paid:true,date:today()});const set=(k,x)=>setV({...v,[k]:x});return <Modal title="Nova venda" onClose={close}>{available.length?<form onSubmit={e=>{e.preventDefault();run(async()=>{await mutate(s=>recordSale(s,v),'Venda registrada');close();});}}><Field label="Produção / lote"><select value={v.productionId} onChange={e=>set('productionId',e.target.value)}>{available.map(p=><option key={p.id} value={p.id}>{p.projectName} · {p.date} · {p.quantity-state.sales.filter(s=>s.productionId===p.id&&!s.cancelledAt).reduce((n,s)=>n+s.quantity,0)} disponíveis</option>)}</select></Field><div className="form-grid"><Num label="Quantidade vendida" min={1} step={1} value={v.quantity} onChange={x=>set('quantity',x)} required/><Num label="Valor total da venda (R$)" value={v.amount} onChange={x=>set('amount',x)} required min={0.01}/><Num label="Taxas desta venda (R$)" value={v.fee} onChange={x=>set('fee',x)}/><Input label="Data da venda" type="date" value={v.date} onChange={e=>set('date',e.target.value)} required/></div><Input label="Cliente (opcional)" value={v.customer} onChange={e=>set('customer',e.target.value)}/><label className="check"><input type="checkbox" checked={v.paid} onChange={e=>set('paid',e.target.checked)}/> Pagamento recebido</label><div className="actions"><Button disabled={busy}>Registrar venda</Button></div></form>:<Empty title="Nenhuma peça disponível" text="Conclua uma impressão na calculadora antes de registrar a venda."/>}</Modal>}
function BarChart({data}){const max=Math.max(...data.map(d=>d.value),1);return <div className="bar-chart">{data.map(d=><div className="chart-column" key={d.name}><span>{d.value?money(d.value):"—"}</span><div className="bar-space"><i style={{height:Math.max(d.value?3:0,d.value/max*100)+'%'}}/></div><small>{d.label||d.name.slice(5).split('-').reverse().join('/')}</small></div>)}</div>}
function Rank({title,data,unit='money'}){return <section className="panel"><h2>{title}</h2>{data.length?data.slice(0,10).map((x,i)=><div className="rank-row" key={x.name}><span className={'rank '+(!i?'first':'')}>{String(i+1).padStart(2,'0')}</span><div className="grow"><b>{x.name}</b><div className="progress slim"><i style={{width:`${x.value/Math.max(data[0].value,1)*100}%`}}/></div></div><strong>{unit==='money'?money(x.value):`${x.value} un.`}</strong></div>):<Empty title="Os números estão a caminho" text="Os rankings aparecem conforme você registra sua atividade."/>}</section>}
function Reports({state,addExpense,mutate,run}){const [from,setFrom]=useState(today().slice(0,7)+'-01'),[to,setTo]=useState(today());const r=report(state,from,to);return <><div className="toolbar"><Input label="De" type="date" value={from} onChange={e=>setFrom(e.target.value)}/><Input label="Até" type="date" value={to} onChange={e=>setTo(e.target.value)}/><Button kind="subtle" onClick={()=>{setFrom('');setTo(today());}}>Todo o período</Button><Button onClick={addExpense}><Plus size={17}/> Despesa extra</Button></div><div className="stats"><Stat label="Faturamento" value={money(r.revenue)} icon={ArrowUpRight} accent/><Stat label="Lucro após despesas" value={money(r.profit)} icon={ChartNoAxesCombined}/><Stat label="Material consumido" value={money(r.material)} icon={Layers}/><Stat label="Energia de produção" value={money(r.energy)} icon={Zap}/></div><div className="dashboard-grid"><Rank title="Peças mais vendidas" data={r.byProduct} unit="quantity"/><Rank title="Melhores meses de vendas" data={r.byMonth}/><Rank title="Dias com maior faturamento" data={r.byDay}/><Rank title="Gastos de material por marca e cor" data={r.byMaterial}/></div><section className="panel"><div className="section-title"><h2>Despesas extras</h2><span>{money(r.expenses)}</span></div><p className="note">Material consumido mede o uso nas impressões. Compras de carretéis no período: {money(r.purchases)}. Não cadastre novamente esses materiais como despesa extra para evitar contar o custo duas vezes.</p>{state.expenses.filter(x=>x.date>=(from||'')&&x.date<=to).map(e=><div className="list-row" key={e.id}><div className="grow"><b>{e.name}</b><small>{e.date} · {e.category}</small></div><strong>{money(e.amount)}</strong><button className="icon" aria-label="Remover despesa" onClick={()=>run(()=>mutate(s=>({...s,expenses:s.expenses.filter(x=>x.id!==e.id)})))}><Trash2 size={16}/></button></div>)}</section><p className="note">Lucro = vendas − custo proporcional das peças vendidas − taxas − despesas extras do período. Produções ainda não vendidas e falhas aparecem no consumo, sem serem abatidas novamente do lucro das vendas.</p></>}
function ExpenseForm({close,mutate,run,busy}){const [v,setV]=useState({name:'',category:'Manutenção',amount:'',date:today()});return <Modal title="Registrar despesa extra" onClose={close}><form onSubmit={e=>{e.preventDefault();run(async()=>{if(!v.name.trim()||!Number.isFinite(Number(v.amount))||Number(v.amount)<=0)throw Error('Informe descrição e valor válido.');await mutate(s=>({...s,expenses:[...s.expenses,{...v,id:uid(),amount:Number(v.amount)}]}));close();});}}><Input label="Descrição" required value={v.name} onChange={e=>setV({...v,name:e.target.value})}/><Field label="Categoria"><select value={v.category} onChange={e=>setV({...v,category:e.target.value})}>{['Manutenção','Ferramentas','Aluguel','Publicidade','Outros'].map(x=><option key={x}>{x}</option>)}</select></Field><div className="form-grid"><Num label="Valor (R$)" min={0.01} required value={v.amount} onChange={x=>setV({...v,amount:x})}/><Input label="Data" type="date" required value={v.date} onChange={e=>setV({...v,date:e.target.value})}/></div><div className="actions"><Button disabled={busy}>Salvar despesa</Button></div></form></Modal>}

function SettingsPage({state,mutate,run,notice,confirm}){const [v,setV]=useState(state.settings),[cityList,setCityList]=useState([]),[loadingCities,setLoadingCities]=useState(false),[password,setPassword]=useState(''),[token,setToken]=useState(''),[repo,setRepo]=useState(''),[working,setWorking]=useState(false),[update,setUpdate]=useState(null),[checkStatus,setCheckStatus]=useState('');const change=(k,x)=>setV({...v,[k]:x});useEffect(()=>{if(!v.state){setCityList([]);return;}let active=true;setLoadingCities(true);cities(v.state).then(data=>{if(active)setCityList(data);}).catch(()=>{if(active)notice('Não foi possível consultar as cidades. Tente novamente com internet.');}).finally(()=>{if(active)setLoadingCities(false);});return()=>{active=false;};},[v.state]);const task=fn=>run(async()=>{setWorking(true);try{await fn();}finally{setWorking(false);}});async function restore(text){const data=await decryptBackup(text,password);confirm({type:'confirm',title:'Restaurar backup?',text:`Este backup contém ${data.projects.length} projetos, ${data.spools.length} carretéis e ${data.sales.length} vendas. Primeiro será solicitado salvar uma cópia dos dados atuais; depois a base local será substituída.`,action:async()=>{const ok=await exportFile(`onca3d-antes-restauracao-${today()}.onca`,await encryptBackup(state,password));if(!ok)throw Error('Restauração cancelada: a cópia de segurança não foi salva.');await mutate(s=>({...data,revision:s.revision}),'Backup restaurado');}});}
return <div className="settings-grid"><section className="panel"><div className="section-title"><h2>Seu ateliê</h2><Settings size={19}/></div><form onSubmit={e=>{e.preventDefault();run(()=>{const tariff=Number(v.tariff),watts=Number(v.watts),lowStock=Number(v.lowStock),monthlyGoal=Number(v.monthlyGoal||0);if(!v.shop.trim()||![tariff,watts,lowStock,monthlyGoal].every(x=>Number.isFinite(x)&&x>=0))throw Error('Preencha os campos com valores válidos.');return mutate(s=>({...s,settings:{...v,tariff,watts,lowStock,monthlyGoal}}),'Configurações salvas');});}}><Input label="Nome do ateliê" required value={v.shop} onChange={e=>change('shop',e.target.value)}/><Num label="Meta de vendas do mês (R$)" value={v.monthlyGoal||0} onChange={x=>change('monthlyGoal',x)}/><Num label="Alerta de estoque abaixo de (g)" value={v.lowStock} onChange={x=>change('lowStock',x)}/><div className="divider"/><h3><Zap size={18}/> Energia da sua região</h3><div className="form-grid"><Field label="Estado"><select value={v.state} onChange={e=>setV({...v,state:e.target.value,city:''})}><option value="">Selecione</option>{UF.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Cidade"><select disabled={loadingCities||!v.state} value={v.city} onChange={e=>change('city',e.target.value)}><option value="">{loadingCities?'Consultando IBGE…':'Selecione'}</option>{v.city&&!cityList.some(c=>c.nome===v.city)&&<option>{v.city}</option>}{cityList.map(c=><option key={c.id}>{c.nome}</option>)}</select></Field></div><TariffLookup uf={v.state} location={`${v.city}${v.state?" / "+v.state:""}`} apply={t=>setV({...v,distributor:t.name,tariff:t.price,tariffDate:t.sourceDate,tariffSource:"aneel",tariffFrom:t.from,tariffTo:t.to})} run={run}/><Input label="Distribuidora da sua conta" value={v.distributor} onChange={e=>change('distributor',e.target.value)} placeholder="Ex.: Enel, Cemig, Light…"/><div className="form-grid"><Num label="Tarifa final (R$/kWh)" value={v.tariff} onChange={x=>change('tariff',x)}/><Num label="Consumo médio da impressora (W)" value={v.watts} onChange={x=>change('watts',x)}/><Input label="Data da referência" type="date" value={v.tariffDate} onChange={e=>change('tariffDate',e.target.value)}/><Field label="Fonte do valor"><select value={v.tariffSource} onChange={e=>change('tariffSource',e.target.value)}><option value="manual">Minha conta de luz</option><option value="aneel">Referência consultada na ANEEL</option><option value="medido">Tarifa ajustada manualmente</option></select></Field></div><p className="note">Use TE + TUSD e adicionais por kWh da conta, com impostos e bandeira. Exclua iluminação pública, multas e serviços. Potência nominal da fonte não é consumo médio.</p><a className="text-button" href="https://www.gov.br/aneel/pt-br/assuntos/tarifas/ranking-das-tarifas" target="_blank" rel="noreferrer">Consultar tarifas oficiais da ANEEL <ArrowUpRight size={15}/></a><p className="note warning">A consulta usa a tarifa residencial convencional B1 da ANEEL, sem impostos e bandeira. Confirme a distribuidora na sua conta e ajuste o valor final por kWh. Cidade e estado não identificam sozinhos a distribuidora. Para tarifa comercial ou branca, use a conta de luz.</p><div className="actions"><Button>Salvar configurações</Button></div></form></section>
<div className="stack"><section className="panel"><div className="section-title"><h2>Seu backup, protegido</h2><ShieldCheck size={20}/></div><p className="muted">Inclui fotos, projetos, estoque e histórico. O arquivo é criptografado com sua senha; guarde-a, pois não existe recuperação por servidor.</p><Input label="Senha de backup (mínimo 10 caracteres)" type="password" autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)}/><div className="two-buttons"><Button disabled={working} onClick={()=>task(async()=>{const body=await encryptBackup(state,password);const ok=await exportFile(`onca3d-backup-${today()}.onca`,body);notice(ok?'Backup preparado. Guarde o arquivo em local seguro.':'Exportação cancelada');})}><Download size={17}/> Exportar backup</Button><label className={'button subtle '+(working?'disabled':'')}><Upload size={17}/> Restaurar arquivo<input type="file" accept=".onca" disabled={working} hidden onChange={e=>{const f=e.target.files?.[0];e.target.value='';if(f)task(async()=>{if(f.size>150*1024*1024)throw Error('Arquivo excede 150 MB.');await restore(await f.text());});}}/></label></div><p className="note">Desinstalar o aplicativo pode apagar os dados locais. Exporte um backup antes.</p><div className="divider"/><h3>Backup individual no GitHub</h3><BackupGuide/><p className="note">Opcional: use um repositório privado da sua própria conta e um token limitado a esse repositório, com permissão Contents: leitura e escrita. A chave fica apenas nesta tela e não entra no backup.</p><Input label="Seu repositório privado" placeholder="seu-usuario/meus-backups" value={repo} onChange={e=>setRepo(normalizeRepository(e.target.value))}/><Input label="Seu token pessoal (somente nesta sessão)" type="password" autoComplete="off" value={token} onChange={e=>setToken(e.target.value)}/><div className="two-buttons"><Button kind="subtle" disabled={working||!token||!repo} onClick={()=>task(async()=>{const body=await encryptBackup(state,password);await githubBackup({token,repo,body});notice('Backup criptografado salvo no seu repositório privado');})}><Upload size={16}/> Enviar backup</Button><Button kind="subtle" disabled={working||!token||!repo} onClick={()=>task(async()=>restore(await githubBackup({token,repo,restore:true})))}><Download size={16}/> Recuperar</Button></div><p className="note">Fotos e registros são enviados em partes, com verificação de integridade. Aguarde o término antes de sair desta tela. O último backup completo é preservado se um envio falhar. Não há sincronização automática entre aparelhos.</p></section>
<UpdatePanel state={state} run={run} notice={notice}/></div></div>}

function normalizeRepository(value){return String(value).trim().replace(/^https?:\/\/(?:www\.)?github\.com\//i,'').replace(/\.git$/,'').replace(/\/$/,'');}

function TariffLookup({location,uf,apply,run}){const [list,setList]=useState([]),[selected,setSelected]=useState(''),[working,setWorking]=useState(false);return <div className="tariff-lookup"><div className="split"><h3>Referência oficial de energia</h3><Button type="button" kind="subtle" disabled={working} onClick={()=>run(async()=>{setWorking(true);try{setList(await fetchTariffs());}finally{setWorking(false);}})}><RefreshCw size={15}/>{working?'Consultando…':'Consultar ANEEL'}</Button></div>{list.length>0&&<><p className="note">{location||'Sua região'}: confirme na conta a distribuidora que atende seu imóvel. A lista inclui as distribuidoras com referência vigente no Brasil.</p><Field label="Distribuidora · tarifa base residencial"><select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Selecione sua distribuidora</option>{[...list].sort((a,b)=>uf==='RJ'?Number(/LIGHT/.test(b.name))-Number(/LIGHT/.test(a.name))||a.name.localeCompare(b.name):a.name.localeCompare(b.name)).map(t=><option key={t.name} value={t.name}>{/LIGHT/.test(t.name)?"Light — Rio de Janeiro (LIGHT SESA)":t.name} · R$ {t.price.toFixed(4)}/kWh</option>)}</select></Field>{selected&&<Button type="button" kind="subtle" onClick={()=>apply(list.find(x=>x.name===selected))}>Usar como referência</Button>}</>}<p className="note">Fonte: ANEEL — Tarifas de aplicação. TE + TUSD, convertidas de R$/MWh para R$/kWh. A referência aplicada fica salva para uso offline.</p></div>}

function Dashboard({state,r,low,go,newProject}){const revenue=r.revenue,cost=r.costSold+r.expenses;const end=new Date(today()+'T12:00:00');const days=Array.from({length:7},(_,i)=>{const d=new Date(end);d.setDate(d.getDate()-6+i);const date=d.toLocaleDateString('en-CA');return {name:date,label:d.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.',''),value:state.sales.filter(s=>!s.cancelledAt&&s.date===date).reduce((n,s)=>n+s.amount,0)};});const total=state.spools.reduce((n,s)=>n+remaining(state,s.id),0);return <><div className="home-profile"><button className="profile-picture" aria-label="Perfil do ateliê" onClick={()=>go('settings')}><img src="./logo.png" alt="Logo JAGUAR LAB"/></button><div><strong>{state.settings.shop}</strong><span>Sua produção no controle.</span></div><span className="badge local-state"><span className="dot"/> No aparelho</span></div><div className="stats overview-stats"><Stat label="Lucro do mês" value={money(r.profit)} icon={Coins} accent/><Stat label="Vendas" value={money(revenue)} icon={ShoppingBag}/><Stat label="Custos das vendas" value={money(cost)} icon={Layers}/></div><div className="dashboard-grid compact-dashboard"><section className="panel week-panel"><div className="section-title"><h2><ChartNoAxesCombined size={19}/> Vendas da semana</h2><span className="subtle-caption">Últimos 7 dias</span></div><BarChart data={days}/></section><section className="panel recent-projects"><div className="section-title"><h2><Printer size={19}/> Seus projetos</h2><button className="text-button" onClick={()=>go('projects')}>Ver todos <ChevronRight size={15}/></button></div>{state.projects.length?state.projects.slice(-3).reverse().map(p=><button className="project-line" key={p.id} onClick={()=>{sessionStorage.setItem('onca-project',p.id);go('calculator');}}><Thumb project={p}/><span className="grow"><b>{p.name}</b><small>{p.model?'Modelo '+p.model.format.toUpperCase():'Projeto cadastrado'}</small></span><ChevronRight size={17}/></button>):<div className="compact-empty"><Package size={30}/><p>Adicione seu primeiro projeto.</p></div>}<Button onClick={newProject}><Plus size={18}/> Novo projeto</Button></section><section className="panel stock-overview"><div className="section-title"><h2><Layers size={19}/> Filamentos</h2><button className="text-button" onClick={()=>go('spools')}>Ver estoque <ChevronRight size={15}/></button></div><div className="inventory-value">{(total/1000).toLocaleString('pt-BR',{maximumFractionDigits:2})}<span> kg disponíveis</span></div>{state.spools.length>0&&<div className="color-inventory">{state.spools.slice(0,12).map(s=><span key={s.id} title={s.name} style={{background:s.color}}/>)}</div>}<p className="note">{state.spools.length} carretéis{low.length?` · ${low.length} com estoque baixo`:' · estoque sob controle'}</p></section><MonthlyGoal state={state} revenue={r.revenue} go={go}/></div></>}

function MonthlyGoal({state,revenue,go}){const goal=Number(state.settings.monthlyGoal||0),percent=goal?Math.min(100,revenue/goal*100):0;return <section className="panel goal-panel"><div className="section-title"><h2><ChartNoAxesCombined size={19}/> Meta do mês</h2>{goal>0&&<span>{percent.toFixed(0)}% alcançado</span>}</div>{goal>0?<><div className="progress"><i style={{width:percent+'%'}}/></div><p>{money(revenue)} <span>de {money(goal)}</span></p></>:<button className="text-button" onClick={()=>go('settings')}>Definir minha meta mensal <ChevronRight size={16}/></button>}</section>}

function SpoolDetails({item,state,close,edit}){const rest=remaining(state,item.id),used=consumed(state,item.id);return <Modal title={item.name} onClose={close}><div className="spool-detail-hero"><Spool color={item.color} size={160}/><div><span className="badge">{item.material}</span><h2>{item.brand}</h2><p>{item.line||'Carretel de filamento'}</p><strong>{rest.toLocaleString('pt-BR',{maximumFractionDigits:1})} <small>g restantes</small></strong></div></div><div className="progress"><i style={{width:Math.max(0,rest/item.initialGrams*100)+'%',background:item.color}}/></div><div className="detail-grid"><div><span>Já utilizado</span><strong>{used.toLocaleString('pt-BR',{maximumFractionDigits:1})} g</strong></div><div><span>Peso inicial</span><strong>{item.initialGrams} g</strong></div><div><span>Preço do carretel</span><strong>{money(item.price)}</strong></div><div><span>Custo por grama</span><strong>R$ {(item.price/item.initialGrams).toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})}</strong></div></div><div className="actions"><Button kind="subtle" onClick={close}>Fechar</Button><Button onClick={()=>edit(item)}>Editar filamento</Button></div></Modal>}

function FilamentPicker({state,value,onChange}){const [open,setOpen]=useState(false);const item=state.spools.find(s=>s.id===value);return <div className="filament-picker"><button type="button" className="picker-trigger" aria-expanded={open} onClick={()=>setOpen(!open)}>{item?<><span className="color-dot" style={{background:item.color}}/><span>{item.material} · {item.name}</span></>:<span>Selecione o filamento</span>}<ChevronRight size={17} className={open?'turned':''}/></button>{open&&<div className="picker-options" role="listbox" aria-label="Carretéis disponíveis">{state.spools.map(s=><button type="button" role="option" aria-selected={s.id===value} key={s.id} onClick={()=>{onChange(s.id);setOpen(false);}}><Spool color={s.color} size={48}/><span><strong>{s.name}</strong><small>{s.brand} · {s.material} · {remaining(state,s.id).toFixed(0)} g</small></span>{s.id===value&&<Check size={17}/>}</button>)}{!state.spools.length&&<p className="note">Cadastre um filamento na aba Estoque.</p>}</div>}</div>}


function Collaboration(){return <section className="panel collaboration-panel"><span className="badge yellow"><Heart size={15}/> COLABORAÇÃO VOLUNTÁRIA</span><img className="support-logo" src="./logo.png" alt="Logo JAGUAR LAB"/><h2>Ajude o JAGUAR LAB a continuar</h2><p>Gostou do aplicativo? Sua colaboração ajuda a manter o projeto e suas próximas atualizações.</p><div className="qr-card"><img src="./donation-qr.png" alt="QR Code para colaboração via Pix, informado pelo criador do projeto"/></div><h3>Como colaborar</h3><p>Abra o aplicativo do seu banco, escolha <b>Pix → Ler QR Code</b> e aponte para este código. No mesmo celular, você pode tirar uma captura da tela e usar a opção do banco para ler uma imagem da galeria.</p><p className="note">Escolha o valor que desejar. A doação é opcional e não é necessária para usar o aplicativo. Confira o destinatário no seu banco antes de confirmar. O JAGUAR LAB não processa pagamentos.</p><span className="thanks"><Heart size={17}/> Obrigado por apoiar o projeto!</span></section>}

createRoot(document.getElementById('root')).render(<App/>);

function UpdatePanel({state,run,notice,autoCheck=false}){const [working,setWorking]=useState(false),[update,setUpdate]=useState(null),[checkStatus,setCheckStatus]=useState('');const task=fn=>run(async()=>{setWorking(true);try{await fn();}finally{setWorking(false);}});useEffect(()=>{if(!autoCheck)return;let active=true;setWorking(true);setCheckStatus('Consultando a versão publicada…');checkUpdate().then(next=>{if(!active)return;setUpdate(next);setCheckStatus(next?`Nova versão ${next.version} disponível. Instalada: ${VERSION}.`:`Consulta concluída. A versão ${VERSION} está atualizada neste canal.`);}).catch(()=>{if(active)setCheckStatus('Não foi possível consultar agora. Confira a internet e tente novamente.');}).finally(()=>{if(active)setWorking(false);});return()=>{active=false;};},[]);return <section className="panel"><div className="section-title"><h2>Atualizações</h2><RefreshCw size={20}/></div><p className="muted">JAGUAR LAB <b>{VERSION}</b> · canal de prévia</p><p className="note">Canal oficial: PeraTV/onca3d-atualizacoes. Nenhum token pessoal é necessário para verificar versões.</p><Button disabled={working} onClick={()=>task(async()=>{setCheckStatus('Consultando a versão publicada…');try{const next=await checkUpdate();setUpdate(next);setCheckStatus(next?`Nova versão ${next.version} disponível. Instalada: ${VERSION}.`:`Consulta concluída. A versão ${VERSION} está atualizada neste canal.`);notice(next?`Versão ${next.version} disponível`:'Consulta concluída: nenhuma nova versão neste canal');}catch(e){setCheckStatus('A consulta falhou. Não foi possível confirmar a versão disponível.');throw e;}})}><RefreshCw size={16}/> Verificar atualização</Button>{checkStatus&&<p className="note" role="status">{checkStatus}</p>}{update&&<div className="update-box"><b>Versão {update.version}</b><p>{update.notes||'Uma nova versão está disponível.'}</p><Button disabled={working} onClick={()=>task(async()=>{await installUpdate(state);notice("Instalador aberto. Confirme a atualização no sistema.");})}><Download size={16}/> Baixar e instalar atualização</Button></div>}<p className="note">Ao atualizar, uma cópia local de recuperação é salva antes de abrir o instalador. No Android, confirme a instalação pelo sistema. Instale por cima, sem desinstalar.</p></section>;}
